<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$u=current_user();$title='Profile';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();dbq('UPDATE users SET fname=?,lname=?,phone=?,address=?,city=?,state=?,country=? WHERE id=?',[post('fname'),post('lname'),post('phone'),post('address'),post('city'),post('state'),post('country'),user_id()]);if(post('password'))dbq('UPDATE users SET password=? WHERE id=?',[password_hash((string)post('password'),PASSWORD_DEFAULT),user_id()]);flash('success','Profile updated.');redirect('profile.php');}require __DIR__.'/includes/header.php';?><div class="card"><h1>My Profile</h1><form method="post"><?=csrf_field()?><div class="form-grid"><?php foreach(['fname','lname','phone','address','city','state','country'] as $c):?><div class="field"><label><?=e(ucwords($c))?></label><input name="<?=e($c)?>" value="<?=e($u[$c]??'')?>"></div><?php endforeach;?><div class="field"><label>New password</label><input type="password" name="password" minlength="8"></div></div><br><button class="btn">Save profile</button></form></div><?php require __DIR__.'/includes/footer.php';?>